// Voice guidance script and clip paths. Owner: Labib (tickets L1 and L6).
//
// The clips are pre-generated by scripts/gen-voice.ts and served as static
// files, so the patient flow never waits on a live ElevenLabs call mid-demo.
//
// The challenge code is different per link, so no clip ever says it out loud.
// Every clip points at the code on the screen instead.

export type Language = "en" | "es";

export type CaptureStep = "welcome" | "write_code" | "frame" | "review" | "sent";

export const CAPTURE_STEPS: CaptureStep[] = ["welcome", "write_code", "frame", "review", "sent"];

export const VOICE_SCRIPT: Record<Language, Record<CaptureStep, string>> = {
  en: {
    welcome:
      "Your clinic asked you to take your pregnancy test at home. This takes about two minutes. Take the test first and wait the full time on its box.",
    write_code:
      "Now write the four characters shown on your screen onto the test, near the result window, with a pen.",
    frame:
      "Hold the test flat under good light and fill the frame. Keep the result window and the code you wrote both visible, then take the photo.",
    review:
      "Check that the lines and the code are sharp. If anything is blurry, retake it. When it looks clear, send it.",
    sent: "Received. Your clinic will review it and will be in touch. You can close this page.",
  },
  es: {
    welcome:
      "Su clínica le pidió hacer la prueba de embarazo en casa. Esto toma unos dos minutos. Haga la prueba primero y espere el tiempo completo indicado en la caja.",
    write_code:
      "Ahora escriba con bolígrafo los cuatro caracteres que aparecen en su pantalla sobre la prueba, cerca de la ventana de resultado.",
    frame:
      "Sostenga la prueba plana con buena luz y llene el encuadre. Deje visibles la ventana de resultado y el código que escribió, y luego tome la foto.",
    review:
      "Revise que las líneas y el código se vean nítidos. Si algo está borroso, tome la foto otra vez. Cuando se vea claro, envíela.",
    sent: "Recibido. Su clínica lo revisará y se comunicará con usted. Puede cerrar esta página.",
  },
};

export function clipPath(language: Language, step: CaptureStep): string {
  return `/audio/${language}/${step}.mp3`;
}

/** On-screen text, which is also the fallback if the clips get cut (see PRD). */
export function stepText(language: Language, step: CaptureStep): string {
  return VOICE_SCRIPT[language][step];
}

